.venv/bin/python - <<'EOF'
import pandas as pd, zipfile
P = pd.read_csv(zipfile.ZipFile('data/raw/csv_pme.zip').open('psam_p23.csv'), dtype={'PUMA':str,'SERIALNO':str}, low_memory=False)
H = pd.read_csv(zipfile.ZipFile('data/raw/csv_hme.zip').open('psam_h23.csv'), dtype={'PUMA':str,'SERIALNO':str}, low_memory=False)
P = P[P.PUMA=='01000']; H = H[H.PUMA=='01000']
print(len(P), len(H))
def show(df, v, tag):
    s=df[v]; w = df['PWGTP' if tag=='P' else 'WGTP']
    top = (w.groupby(s).sum()/w[s.notna()].sum()).sort_values(ascending=False).head(4)
    t = ", ".join(f"{k:g}:{p:.0%}" for k,p in top.items()) if s.nunique()<40 else f"median {s.median():g}"
    print(f"{tag} {v:11s} filled {s.notna().mean():4.0%}  n_distinct {s.nunique():4d}  {t}")
for v in "DIS DEAR DEYE DREM DPHY DDRS DOUT HICOV PUBCOV HINS4 MAR NATIVITY CIT LANX ENG MIL JWTRNS JWMNP WKHP COW OCCP INDP PINCP WAGP SSP SSIP PAP SCH SCHG MIG FER GCL".split():
    if v in P: show(P,v,'P')
for v in "HHT MULTG HHL LNGI VEH ACCESSINET HISPEED GRPIP OCPIP RNTP SMOCP R65 NOC HUPAC WIF FS CPLT PARTNER".split():
    if v in H: show(H,v,'H')
EOF

