    def schema(self) -> dict:
        base = self.catalog.schema()
        totals = [{"id": k, "label": v, "kind": "total", "unit": "household" if k != "population" else "person",
                   "universe": None, "available": True, "categories": [{"id": "total", "label": v}]}
